const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Madre de Dios region
  const madreDeDios = ee.Geometry.Rectangle([-72.5, -13.5, -68.5, -9.5]);

  // 2. Use Hansen Global Forest Change dataset
  const hansen = ee.Image('UMD/hansen/global_forest_change_2023_v1_11');

  // Get forest cover in 2000 (baseline)
  const forestCover2000 = hansen.select('treecover2000');

  // Get loss year band (values 1-23 for years 2001-2023)
  const lossYear = hansen.select('lossyear');

  // 3. Calculate forest for 2013 and 2018
  // Forest in 2013: areas with >30% tree cover in 2000 that hadn't been lost by 2013
  const lossBy2013 = lossYear.lte(13).and(lossYear.gte(1));
  const forest2013 = forestCover2000.gt(30).and(lossBy2013.not());

  // Forest in 2018: areas with >30% tree cover in 2000 that hadn't been lost by 2018
  const lossBy2018 = lossYear.lte(18).and(lossYear.gte(1));
  const forest2018 = forestCover2000.gt(30).and(lossBy2018.not());

  // 4. Calculate forest area for both years
  const pixelArea = ee.Image.pixelArea();

  const forestArea2013 = forest2013.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: madreDeDios,
    scale: 3000,
    maxPixels: 1e9
  });

  const forestArea2018 = forest2018.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: madreDeDios,
    scale: 3000,
    maxPixels: 1e9
  });

  // Get pixel counts for validation
  const count2013 = forest2013.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: madreDeDios,
    scale: 3000,
    maxPixels: 1e9
  });

  const count2018 = forest2018.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: madreDeDios,
    scale: 3000,
    maxPixels: 1e9
  });

  // 5. Get results
  const area2013 = forestArea2013.get('treecover2000').getInfo();
  const area2018 = forestArea2018.get('treecover2000').getInfo();
  const pixels2013 = count2013.get('treecover2000').getInfo();
  const pixels2018 = count2018.get('treecover2000').getInfo();

  // 6. Validation and answer
  if (area2013 === null || area2018 === null) {
    console.log("Calculation failed - null result");
    console.log("<answer>C3</answer>");
    return;
  }

  if (pixels2013 === 0 || pixels2018 === 0) {
    console.log("No valid pixels found");
    console.log("<answer>C2</answer>");
    return;
  }

  // Convert to km²
  const area2013_km2 = area2013 / 1e6;
  const area2018_km2 = area2018 / 1e6;
  const change = area2018_km2 - area2013_km2;
  const percentChange = ((change / area2013_km2) * 100);

  console.log(`Forest 2013: ${area2013_km2.toFixed(0)} km² (${pixels2013} pixels)`);
  console.log(`Forest 2018: ${area2018_km2.toFixed(0)} km² (${pixels2018} pixels)`);
  console.log(`Change: ${change.toFixed(0)} km² (${percentChange.toFixed(2)}%)`);

  if (area2018 < area2013) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
